const s=window.state; if(s.nt===undefined)s.nt=0; s.nt+=0.003; const d=s.nt;
if(!s.nb){ s.nb=createGraphics(width,height); s.nb.colorMode(HSB,360,100,100,100);
  const g=s.nb; g.background(250,80,4); g.noStroke();
  for(let i=0;i<600;i++){ const x=Math.random()*width,y=Math.random()*height;
    const h=[260,300,190,330][i%4]; g.fill(h,70,50,6); g.ellipse(x,y,60+Math.random()*180); }
}
image(s.nb,0,0);
// slow drifting hue veil
push(); blendMode(ADD);
for(let i=0;i<3;i++){ const x=width*(0.3+0.2*i)+Math.sin(d+i)*80, y=height*0.4+Math.cos(d*0.7+i)*60;
  noStroke(); fill([280,190,330][i],80,60,8); ellipse(x,y,300,220); }
