const s=window.state; if(s.ct===undefined)s.ct=0; s.ct+=0.03; const d=s.ct;
// vignette + slow color breathing over everything (drawn first-ish; keep subtle)
push(); blendMode(ADD);
const pulse=0.5+0.5*Math.sin(d*0.8);
noStroke(); fill(280,70,40, 4+pulse*6); rect(0,0,width,height);
pop();
// dark vignette edges
push(); noFill();
for(let i=0;i<80;i++){ stroke(250,60,3, i*0.6); strokeWeight(2); rect(i,i,width-2*i,height-2*i); }
pop();

const s=window.state; if(s.st2===undefined)s.st2=0; s.st2+=0.01; const d=s.st2;
if(!s.stars){ s.stars=[]; for(let i=0;i<160;i++)s.stars.push({x:Math.random()*width,y:Math.random()*height,z:Math.random(),ph:Math.random()*6.28}); }
noStroke();
for(const st of s.stars){ st.ph+=0.03; const tw=0.5+0.5*Math.sin(st.ph);
  fill(0,0,100,30+tw*60*st.z); const r=1+st.z*2.5; ellipse(st.x,st.y,r,r);
  st.x-=0.15*st.z; if(st.x<0)st.x=width; }
// constellation links
stroke(190,40,100,25); strokeWeight(1);
for(let i=0;i<s.stars.length;i+=17){ const a=s.stars[i],b=s.stars[(i+9)%s.stars.length];
  if(Math.hypot(a.x-b.x,a.y-b.y)<220) line(a.x,a.y,b.x,b.y); }

const s=window.state; if(s.gt3===undefined)s.gt3=0; s.gt3+=0.0015; const d=s.gt3;
const hz=height*0.7;
const x=width*0.7, y=hz - Math.sin(d)*height*0.3 + height*0.05, r=Math.min(width,height)*0.28;
push();
drawingContext.shadowBlur=60; drawingContext.shadowColor='hsl(30,80%,50%)';
noStroke(); fill(28,60,55); ellipse(x,y,r*2,r*2);
drawingContext.shadowBlur=0;
// bands
for(let i=-3;i<=3;i++){ fill(28,60,55+i*4,50); ellipse(x,y+i*r*0.22,r*2*Math.cos(i*0.3),r*0.3); }
// terminator
fill(28,80,12,45); arc(x,y,r*2,r*2,-0.8,2.34,PIE);
// rings
push(); translate(x,y); rotate(-0.4); noFill();
for(let k=0;k<3;k++){ stroke(40,40,100,60-k*15); strokeWeight(6-k*1.5); ellipse(0,0,r*3.4+k*14,r*1.1+k*5); }
pop();
pop();

const s=window.state; if(!s.com){ s.com=[]; for(let i=0;i<5;i++)s.com.push({x:Math.random()*width,y:Math.random()*height*0.6,v:3+Math.random()*4,len:60+Math.random()*80,hue:[190,45,300][i%3]}); }
push(); blendMode(ADD);
for(const c of s.com){ c.x+=c.v; c.y+=c.v*0.4;
  if(c.x>width+100||c.y>height){ c.x=-80; c.y=Math.random()*height*0.5; }
  for(let t=0;t<c.len;t+=3){ const a=map(t,0,c.len,80,0); stroke(c.hue,70,100,a); strokeWeight(map(t,0,c.len,3,0.3));
    point(c.x-t, c.y-t*0.4); }
  noStroke(); fill(0,0,100,90); ellipse(c.x,c.y,5,5);
}
