const s=window.state; if(s.pt2===undefined)s.pt2=0; s.pt2+=0.005; const d=s.pt2;
if(!s.plan){ s.plan=[]; for(let i=0;i<4;i++)s.plan.push({cx:width*(0.2+0.22*i),cy:height*(0.2+0.12*(i%2)),r:30+Math.random()*40,hue:[30,200,330,150][i],ph:Math.random()*6.28,ring:Math.random()<.5}); }
for(const p of s.plan){ p.ph+=0.008; const x=p.cx+Math.cos(p.ph)*20, y=p.cy+Math.sin(p.ph*1.3)*14;
  noStroke();
  drawingContext.shadowBlur=30; drawingContext.shadowColor='hsl('+p.hue+',80%,55%)';
  fill(p.hue,70,70); ellipse(x,y,p.r*2,p.r*2);
  drawingContext.shadowBlur=0;
  // terminator shadow
  fill(p.hue,80,15,55); arc(x,y,p.r*2,p.r*2,-1.0,2.14,PIE);
  // bands
  fill(p.hue,60,90,25); ellipse(x,y-p.r*0.3,p.r*1.8,p.r*0.4);
  if(p.ring){ push(); translate(x,y); rotate(-0.5); noFill(); stroke(p.hue,50,100,70); strokeWeight(4); ellipse(0,0,p.r*3.2,p.r*1.1); pop(); }
}

const s=window.state; if(s.wt===undefined)s.wt=0; s.wt+=0.02; const d=s.wt;
if(!s.portal){ s.portal={x:width*0.5,y:height*0.4,tx:width*0.5,ty:height*0.4,rt:0}; s.emit=[]; }
const p=s.portal;
if(Math.abs(p.x-p.tx)<8&&Math.abs(p.y-p.ty)<8){ p.tx=width*(0.2+0.6*((Math.sin(d*1.7)*0.5+0.5))); p.ty=height*(0.2+0.4*((Math.cos(d*1.1)*0.5+0.5))); }
p.x+=(p.tx-p.x)*0.012; p.y+=(p.ty-p.y)*0.012; p.rt+=0.04;
// emit
if(s.emit.length<80){ const a=Math.random()*6.28; s.emit.push({x:p.x,y:p.y,vx:Math.cos(a)*(1+Math.random()*3),vy:Math.sin(a)*(1+Math.random()*3)*0.7,life:1,hue:(d*40)%360}); }
push(); blendMode(ADD);
// particles fly out then get sucked back
for(const e of s.emit){ e.x+=e.vx; e.y+=e.vy; e.vx*=0.98; e.vy*=0.98; e.life-=0.012;
  const dx=p.x-e.x,dy=p.y-e.y; if(e.life<0.5){ e.vx+=dx*0.002; e.vy+=dy*0.002; }
  noStroke(); fill(e.hue,70,100,e.life*80); ellipse(e.x,e.y,3,3); }
s.emit=s.emit.filter(e=>e.life>0);
// vortex
translate(p.x,p.y); noFill();
for(let i=0;i<44;i++){ const a=i*0.5+p.rt; const r=6+i*3.4;
  stroke((d*40+i*8)%360,80,100,map(i,0,44,90,0)); strokeWeight(2);
  const x=Math.cos(a)*r,y=Math.sin(a)*r*0.7;
  if(i>0){ const a0=(i-1)*0.5+p.rt,r0=6+(i-1)*3.4; line(Math.cos(a0)*r0,Math.sin(a0)*r0*0.7,x,y); } }
noStroke(); fill(0,0,100,80); ellipse(0,0,12,10); fill(280,60,100,30); ellipse(0,0,46,34);
pop();

const S=window.state; if(!S.flock){ S.flock=[]; for(let i=0;i<40;i++)S.flock.push({x:Math.random()*width,y:Math.random()*height*0.6,vx:(Math.random()-.5)*2,vy:(Math.random()-.5)*2}); }
const f=S.flock; const cx=f.reduce((a,b)=>a+b.x,0)/f.length, cy=f.reduce((a,b)=>a+b.y,0)/f.length;
push(); blendMode(ADD);
for(const b of f){
  // cohesion + wander
  b.vx+=(cx-b.x)*0.0006+(Math.random()-.5)*0.3;
  b.vy+=(cy-b.y)*0.0006+(Math.random()-.5)*0.3;
  // separation
  for(const o of f){ if(o===b)continue; const dx=b.x-o.x,dy=b.y-o.y,dd=dx*dx+dy*dy; if(dd<500&&dd>0){ b.vx+=dx/dd*4; b.vy+=dy/dd*4; } }
  const sp=Math.hypot(b.vx,b.vy); if(sp>3){ b.vx=b.vx/sp*3; b.vy=b.vy/sp*3; }
  b.x+=b.vx; b.y+=b.vy;
  if(b.x<0)b.x=width; if(b.x>width)b.x=0; if(b.y<0)b.y=height*0.6; if(b.y>height*0.6)b.y=0;
  const a=Math.atan2(b.vy,b.vx);
  stroke(190,60,100,70); strokeWeight(1.5); noFill();
  push(); translate(b.x,b.y); rotate(a);
  line(0,0,-6,-3); line(0,0,-6,3); pop();
}
pop();

const s=window.state; const hz=height*0.7;
if(!s.ridge){ s.ridge=[]; let x=-20; while(x<width+40){ const w=30+Math.random()*60; const h=60+Math.random()*180; s.ridge.push({x,w,h,hue:[280,190,320][Math.floor(Math.random()*3)]}); x+=w*0.7; } }
for(const b of s.ridge){ noStroke();
  fill(b.hue,60,10); triangle(b.x,hz,b.x+b.w/2,hz-b.h,b.x+b.w,hz);
  stroke(b.hue,80,100,70); strokeWeight(1.5); noFill();
  line(b.x,hz,b.x+b.w/2,hz-b.h); line(b.x+b.w/2,hz-b.h,b.x+b.w,hz);
}
// glow floor
noStroke(); for(let i=0;i<40;i++){ fill(280,60,100,3); rect(0,hz+i,width,2); }

const S=window.state; if(!S.jelly){ S.jelly=[]; for(let i=0;i<7;i++)S.jelly.push({x:Math.random()*width,y:height*(0.4+Math.random()*0.4),s:26+Math.random()*24,ph:Math.random()*6.28,vy:-0.2-Math.random()*0.3,hue:[300,190,45,160][i%4]}); }
for(const j of S.jelly){ j.ph+=0.05; j.y+=j.vy+Math.sin(j.ph)*0.3; j.x+=Math.sin(j.ph*0.5)*0.4;
  if(j.y<-40){ j.y=height+40; j.x=Math.random()*width; }
  const s=j.s; push(); translate(j.x,j.y);
  drawingContext.shadowBlur=20; drawingContext.shadowColor='hsl('+j.hue+',80%,60%)';
  noStroke(); fill(j.hue,70,100,50); const pulse=1+0.15*Math.sin(j.ph);
  arc(0,0,s*2*pulse,s*2*pulse,PI,TWO_PI); rect(-s*pulse,0,s*2*pulse,2);
  drawingContext.shadowBlur=0;
  stroke(j.hue,60,100,40); strokeWeight(1.5);
  for(let t=0;t<6;t++){ const tx=-s*0.7+t*s*0.28; beginShape(); noFill();
    for(let y=0;y<s*1.6;y+=6) vertex(tx+Math.sin(y*0.1+j.ph+t)*5, y); endShape(); }
  pop();
}

const s=window.state; if(!s.dust){ s.dust=[]; for(let i=0;i<90;i++)s.dust.push({x:Math.random()*width,y:Math.random()*height,vx:-0.3-Math.random()*0.5,ph:Math.random()*6.28,hue:[190,300,45][i%3]}); }
noStroke();
for(const p of s.dust){ p.ph+=0.04; p.x+=p.vx; p.y+=Math.sin(p.ph)*0.3;
  if(p.x<0){p.x=width;p.y=Math.random()*height;}
  fill(p.hue,50,100,30+Math.sin(p.ph)*30); ellipse(p.x,p.y,2,2); }

const S=window.state; if(!S.aliens){ S.aliens=[]; for(let i=0;i<3;i++)S.aliens.push({x:Math.random()*width,y:height*0.9,s:120+Math.random()*80,vx:(Math.random()<.5?1:-1)*(0.3+Math.random()*0.4),ph:Math.random()*6.28,hue:[160,300,190][i]}); }
for(const c of S.aliens){ c.x+=c.vx; c.ph+=0.04;
  if(c.x<-250)c.x=width+250; if(c.x>width+250)c.x=-250;
  const s=c.s,dir=Math.sign(c.vx); push(); translate(c.x,c.y); scale(dir,1);
  drawingContext.shadowBlur=22; drawingContext.shadowColor='hsl('+c.hue+',90%,60%)';
  stroke(c.hue,90,100,90); strokeWeight(2.5); fill(c.hue,60,8);
  // tall stalked head alien body
  beginShape();
  vertex(-s*0.25,0); vertex(-s*0.2,-s*0.5); vertex(-s*0.28,-s*0.7);
  vertex(-s*0.12,-s*0.62); vertex(-s*0.1,-s*0.9); // stalk
  vertex(0,-s*1.0); vertex(s*0.1,-s*0.9); vertex(s*0.12,-s*0.62);
  vertex(s*0.28,-s*0.7); vertex(s*0.2,-s*0.5); vertex(s*0.25,0);
  endShape(CLOSE);
  // eye pods
  drawingContext.shadowBlur=0; noStroke(); fill(0,0,100,90);
  ellipse(-s*0.05,-s*0.92,s*0.06); ellipse(s*0.05,-s*0.92,s*0.06);
  // legs
  stroke(c.hue,90,100,80); strokeWeight(3); const st=Math.sin(c.ph)*s*0.08;
  line(-s*0.1,0,-s*0.1+st,s*0.12); line(s*0.1,0,s*0.1-st,s*0.12);
  pop();
}

const s=window.state;
if(!s.poem2){
  s.poem2=[
    ["I.","In the hour with no name","the machines dream in color."],
    ["II.","A comet drags its silver hair","across the sleeping boulevards."],
    ["III.","We are small and lit from within,","filaments in a vast dark bulb."],
    ["IV.","The rain falls upward tonight,","returning to the wound it fell from."],
    ["V.","Every window is a tiny sun","somebody forgot to turn off."],
    ["VI.","Stay. The horizon is only","a door we haven't opened yet."],
    ["VII.","When the grid dims, remember:","you were the current all along."]
  ];
  s.pIdx=0; s.pT=0;
}
s.pT++;
const HOLD=420;
if(s.pT>HOLD){ s.pT=0; s.pIdx=(s.pIdx+1)%s.poem2.length; }
const st=s.poem2[s.pIdx];
const fade=Math.min(1, Math.min(s.pT, HOLD-s.pT)/50);
const t=s.pT;
push();
textAlign(LEFT,CENTER); textFont('Courier New');
const x0=width*0.1, y0=height*0.18;
// roman numeral — large, ghosted
textSize(Math.min(width*0.09,90)); textStyle(BOLD);
fill(45,90,100,18*fade); text(st[0], x0-4, y0+height*0.05);
textStyle(NORMAL);
// lines type-on
for(let i=1;i<st.length;i++){
  const sz=Math.min(width*0.03,30); textSize(sz);
  const line=st[i];
  const chars=Math.min(line.length, Math.floor((t-i*10)/1.2));
  const shown=chars>0?line.slice(0,chars):"";
  // glow
  fill(320,90,100,30*fade); text(shown, x0+2, y0+ (i-1)*sz*1.7+2);
  fill(50,20,100,95*fade); text(shown, x0, y0+ (i-1)*sz*1.7);
  // cursor
  if(chars<line.length && chars>=0 && (Math.floor(t/15)%2===0)){
    const w=textWidth(shown); fill(190,80,100,90*fade); rect(x0+w+2, y0+(i-1)*sz*1.7-sz*0.4, sz*0.5, sz*0.9);
  }
}
// left margin rule
stroke(190,70,100,50*fade); strokeWeight(2); line(x0-16,y0-10,x0-16,y0+ (st.length-1)*30*1.7);
pop();
